import{_ as d,a as t,p as e,o as i}from"./index-CVmwAqS1.js";const s={},n={class:"roadmap-view container"};function o(r,a){return i(),t("div",n,[...a[0]||(a[0]=[e('<div class="roadmap-header" data-v-647dd2a3><h1 data-v-647dd2a3>Roadmap</h1><p class="lead" data-v-647dd2a3>Development plans for the Entgl platform and its services.</p></div><div class="timeline" data-v-647dd2a3><div class="timeline-item animate-fade-in" style="animation-delay:0.1s;" data-v-647dd2a3><div class="timeline-marker released" data-v-647dd2a3></div><div class="timeline-content" data-v-647dd2a3><h3 data-v-647dd2a3>v2.1 Released <span class="badge-latest" data-v-647dd2a3>Latest</span></h3><ul class="feature-list" data-v-647dd2a3><li data-v-647dd2a3><strong data-v-647dd2a3>ContentHash on DocumentMetadata</strong><p data-v-647dd2a3>SHA-256 deterministic content hash via canonical JSON normalization for fast integrity verification and optimistic sync decisions.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>P2P Sync Correctness</strong><p data-v-647dd2a3>Improved op-log ordering, hash-chain validation, and vector clock conflict resolution across larger mesh topologies.</p></li></ul></div></div><div class="timeline-item animate-fade-in" style="animation-delay:0.15s;" data-v-647dd2a3><div class="timeline-marker released" data-v-647dd2a3></div><div class="timeline-content" data-v-647dd2a3><h3 data-v-647dd2a3>v2.0 Released</h3><ul class="feature-list" data-v-647dd2a3><li data-v-647dd2a3><strong data-v-647dd2a3>Platform Upgrade — .NET 10</strong><p data-v-647dd2a3>Dropped netstandard2.0 / .NET 6 / .NET 8 in favor of netstandard2.1 + net10.0. All Microsoft.Extensions and EF Core packages updated to 10.0.x.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>Dynamic Database Paths</strong><p data-v-647dd2a3>Per-node configurable database file paths resolved at runtime, enabling multi-tenant and containerized deployments.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>EntglDbNodeService (centralized host)</strong><p data-v-647dd2a3>Single hosted service managing all sync lifecycle: discovery, gossip, oplog, snapshot, and remote peer management.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>Remote Peer Auto-Sync</strong><p data-v-647dd2a3>Remote peers stored in <code data-v-647dd2a3>_system_remote_peers</code> collection; sync engine automatically connects, reconnects, and removes stale entries.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>Fully Async BLite Integration</strong><p data-v-647dd2a3>BLite 3.7.0 persistence layer rewritten with async/await throughout for improved throughput on mobile and server deployments.</p></li></ul></div></div><div class="timeline-item animate-fade-in" style="animation-delay:0.2s;" data-v-647dd2a3><div class="timeline-marker released" data-v-647dd2a3></div><div class="timeline-content" data-v-647dd2a3><h3 data-v-647dd2a3>v1.0 Released</h3><ul class="feature-list" data-v-647dd2a3><li data-v-647dd2a3><strong data-v-647dd2a3>Sync Middleware Identity</strong><p data-v-647dd2a3>First stable release: EntglDb positions itself as a sync layer, not a database. Clear separation of persistence (BLite, EF Core) from synchronization logic.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>DocumentStore Pattern</strong><p data-v-647dd2a3>Introduced <code data-v-647dd2a3>BLiteDocumentStore&lt;T&gt;</code> and <code data-v-647dd2a3>EfCoreDocumentStore&lt;T&gt;</code> base classes. Call <code data-v-647dd2a3>WatchCollection()</code> to register collections for sync.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>VectorClockService</strong><p data-v-647dd2a3>Centralized vector clock management for causally consistent conflict detection across the mesh.</p></li></ul></div></div><div class="timeline-item animate-fade-in" style="animation-delay:0.25s;" data-v-647dd2a3><div class="timeline-marker released" data-v-647dd2a3></div><div class="timeline-content" data-v-647dd2a3><h3 data-v-647dd2a3>v0.9 Released</h3><ul class="feature-list" data-v-647dd2a3><li data-v-647dd2a3><strong data-v-647dd2a3>ASP.NET Core Stability</strong><p data-v-647dd2a3>Production hardening for server-hosted nodes with health checks, structured logging, and graceful shutdown.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>EF Core Improvements</strong><p data-v-647dd2a3>Improved EF Core document store with migration support for relational backends (PostgreSQL, SQL Server).</p></li></ul></div></div><div class="timeline-item animate-fade-in" style="animation-delay:0.3s;" data-v-647dd2a3><div class="timeline-marker released" data-v-647dd2a3></div><div class="timeline-content" data-v-647dd2a3><h3 data-v-647dd2a3>v0.8.0 Released</h3><ul class="feature-list" data-v-647dd2a3><li data-v-647dd2a3><strong data-v-647dd2a3>Dynamic Reconfiguration</strong><p data-v-647dd2a3>Change server roles, listening ports, and database identity without process restarts.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>Known Peers &amp; Leader Election</strong><p data-v-647dd2a3>Support for persistent static peers and automated Bully Algorithm for cloud gateway election.</p></li></ul></div></div><div class="timeline-item animate-fade-in" style="animation-delay:0.35s;" data-v-647dd2a3><div class="timeline-marker released" data-v-647dd2a3></div><div class="timeline-content" data-v-647dd2a3><h3 data-v-647dd2a3>v0.7.0 Released</h3><ul class="feature-list" data-v-647dd2a3><li data-v-647dd2a3><strong data-v-647dd2a3>Protocol v4 &amp; Brotli Compression</strong><p data-v-647dd2a3>Unified secure transport with native Brotli compression for efficient synchronization.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>Unified Versioning</strong><p data-v-647dd2a3>All core packages (.NET, Kotlin, Node.js) synchronized to v0.7.0.</p></li></ul></div></div><div class="timeline-item animate-fade-in" style="animation-delay:0.4s;" data-v-647dd2a3><div class="timeline-marker future" data-v-647dd2a3></div><div class="timeline-content" data-v-647dd2a3><h3 data-v-647dd2a3>Near-Term Roadmap</h3><ul class="feature-list" data-v-647dd2a3><li data-v-647dd2a3><strong data-v-647dd2a3>TLS / Certificate-Based Transport</strong><p data-v-647dd2a3>Replace shared-secret HMAC auth with per-node certificates for zero-trust, certificate-pinned LAN deployments.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>Merkle Tree Sync Optimization</strong><p data-v-647dd2a3>Use Merkle trees as a fast diff mechanism to reduce the amount of op-log exchanged during reconciliation.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>Admin Dashboard (EntglStudio)</strong><p data-v-647dd2a3>Browser-based UI for monitoring mesh topology, op-log health, peer status, and conflict history.</p></li></ul></div></div><div class="timeline-item animate-fade-in" style="animation-delay:0.45s;" data-v-647dd2a3><div class="timeline-marker future" data-v-647dd2a3></div><div class="timeline-content" data-v-647dd2a3><h3 data-v-647dd2a3>Cross-Platform Expansion</h3><ul class="feature-list" data-v-647dd2a3><li data-v-647dd2a3><strong data-v-647dd2a3>React Native (in progress)</strong><p data-v-647dd2a3>Native module wrapping the Kotlin core for iOS and Android. Exposes the same DocumentStore API surface as the .NET reference implementation.</p></li><li data-v-647dd2a3><strong data-v-647dd2a3>Browser / WASM</strong><p data-v-647dd2a3>WebAssembly port enabling web applications to participate in the mesh via WebSocket relay nodes.</p></li></ul></div></div></div>',2)])])}const v=d(s,[["render",o],["__scopeId","data-v-647dd2a3"]]);export{v as default};
